# Actual MCP stdio -> real native sequence boundary. No fake native replies.
param([Parameter(Mandatory=$true)][string]$RepoRoot,[string]$McpBuildDir,[string]$CliDir,[string]$NodeExe,[string]$Out)
. "$PSScriptRoot\_vcvars.ps1";$vcDir=Get-VcVarsDir
$ErrorActionPreference='Stop';$RepoRoot=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $RepoRoot).Path)
if($PSVersionTable.PSVersion.Major-lt7){throw 'PowerShell7 is required for original ProcessStartInfo.ArgumentList and UTF8 receipts'}
if(-not$McpBuildDir){$McpBuildDir=Join-Path $RepoRoot 'mcp/build'};$McpBuildDir=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $McpBuildDir).Path)
if(-not$McpBuildDir.StartsWith($RepoRoot+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Built MCP must stay within private root'}
if(-not$CliDir){$CliDir=Join-Path $RepoRoot 'dist'};$CliDir=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $CliDir).Path)
if(-not$NodeExe){$application=@(Get-Command node.exe -CommandType Application -ErrorAction Stop)|Select-Object -First 1;$NodeExe=$application.Source};$NodeExe=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $NodeExe).Path)
if(-not$Out){$Out=Join-Path $RepoRoot '_scratch/sequence_wait_native'};$outRoot=[IO.Path]::GetFullPath($Out);if(-not$outRoot.StartsWith($RepoRoot+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Out must stay within private root'}
$run=Join-Path $outRoot ('run_'+[guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($run);[void][IO.Directory]::CreateDirectory("$run/temp");[void][IO.Directory]::CreateDirectory("$run/captures")
$checks=[Collections.Generic.List[object]]::new();$arches=[Collections.Generic.List[object]]::new();$cases=[Collections.Generic.List[object]]::new();$calls=[Collections.Generic.List[object]]::new();$processes=[Collections.Generic.List[object]]::new();$pins=[Collections.Generic.List[object]]::new();$rpcCalls=[Collections.Generic.List[object]]::new()
$complete=$false;$instrument=$true;$sourceStable=$false;$current=$null;$server=$null;$serial=0;$token=0;$rpcId=0;$problem=$null;$owner='sf5-'+[guid]::NewGuid().ToString('N')

function Check([bool]$Good,[string]$Name){$checks.Add(@{pass=$Good;name=$Name});Write-Host "$(if($Good){'PASS'}else{'FAIL'}) $Name"}
function Require([bool]$Good,[string]$Name){if(-not$Good){throw $Name}}
function Pin([string]$Path){$pins.Add(@{path=$Path;sha256=(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash;bytes=(Get-Item -LiteralPath $Path).Length})}
function Rows([string]$Path){if(Test-Path -LiteralPath $Path){foreach($line in ((Get-Content -LiteralPath $Path -Raw)-split'\r?\n')){if($line.StartsWith('{')-and$line.EndsWith('}')){$line|ConvertFrom-Json}}}}
function Live($T){$r=ReadRetainedImage $T.process $T.path $T.created $T.retained_handle;$T.latest=$r;Require $r.matched 'fresh exact retained kernel fixture identity'}
function NewTracked($P,[string]$Image){
 # Record the original returned object BEFORE any metadata check can throw.
 $t=@{process=$P;pid=0;path=$Image;created=[long]0;retained_handle=[long]0;cache=$null;cleanup=$null;startup_error=$null};$processes.Add($t)
 try{$t.pid=$P.Id;$t.retained_handle=$P.Handle.ToInt64()}catch{$t.startup_error=$_.Exception.Message};return $t
}
function ValidateTracked($T){Require ($T.retained_handle-ne0-and-not$T.startup_error) 'original process handle retained';$T.created=$T.process.StartTime.ToUniversalTime().Ticks;$seen=ObserveStartupImage $T.process $T.path $T.created $T.retained_handle;$T.startup=$seen;Require $seen.matched 'exact owned startup image/PID/creation';$T.cache=New-ViStrictCliStartupCache (ReadRetainedImage $T.process $T.path $T.created $T.retained_handle) $T.retained_handle ([uint32]$T.pid) $T.created $T.path}
function Finish($T){if(-not$T-or$T.cleanup){return};try{$T.cleanup=AccountOrReapCli $T.process $T.path $T.created $T.retained_handle ([uint32]$T.pid) $T.cache}catch{$T.cleanup=@{completion_owned=$false;reaped=$false;termination_attempted=$false;error=$_.Exception.Message}};if(-not$T.cleanup.completion_owned-or$T.cleanup.error){$script:instrument=$false;Write-Warning ('Owned cleanup/accounting failed: '+$T.cleanup.error)}}
function RunOwned([string]$Image,[string[]]$Arguments,[int]$Budget=10000,[Threading.EventWaitHandle]$StartupGate=$null){
 $Image=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $Image).Path)
 $script:serial++;$prefix=Join-Path $run ('call_'+$serial);$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$Image;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$si.WorkingDirectory=$run;$si.Environment['TEMP']="$run\temp";$si.Environment['TMP']="$run\temp";foreach($arg in $Arguments){[void]$si.ArgumentList.Add($arg)}
 $p=[Diagnostics.Process]::new();$p.StartInfo=$si;$t=$null;$outTail=$null;$errTail=$null;$record=@{image=$Image;arguments=$Arguments;exit=$null;stdout='';stderr='';cleanup=$null};$calls.Add($record)
 try{Require ($p.Start()) 'owned compiler/CLI started';$t=NewTracked $p $Image;$outTail=[ViWndProcAwTail]::new($p.StandardOutput);$errTail=[ViWndProcAwTail]::new($p.StandardError);ValidateTracked $t;if($StartupGate){Require ($StartupGate.Set()) 'release private startup gate only after strict live kernel identity'};Require ($p.WaitForExit($Budget)) 'owned compiler/CLI bounded exit';$proof=Get-ViExitedCliAccounting $t.retained_handle ([uint32]$t.pid) $t.created $Image $t.cache;Require (Test-ViExitedCliAccounting $proof) 'readonly original-handle CLI exit accounting';$record.exit=[BitConverter]::ToInt32([BitConverter]::GetBytes([uint32]$proof.native_exit_code),0);$record.exit_accounting=$proof
  $null=$outTail.Wait(500);$null=$errTail.Wait(500);$record.stdout=$outTail.Text();$record.stderr=$errTail.Text();$record.stdout_complete=$outTail.Complete;$record.stderr_complete=$errTail.Complete
  Require ($outTail.Complete-and$errTail.Complete-and-not$outTail.Error-and-not$errTail.Error-and$outTail.Characters-le65536-and$errTail.Characters-le65536) 'bounded complete separate stdout/stderr'
  return $record
 }finally{try{if($t){Finish $t;$record.cleanup=$t.cleanup}}finally{
   if($outTail){$null=$outTail.Wait(500);$record.stdout=$outTail.Text()};if($errTail){$null=$errTail.Wait(500);$record.stderr=$errTail.Text()};[IO.File]::WriteAllText($prefix+'.stdout.log',$record.stdout);[IO.File]::WriteAllText($prefix+'.stderr.log',$record.stderr);if($t){$t.process.Dispose();$t.Remove('process')};$p.Dispose()
  }}
}
function Invoke-ViSequenceCli([string[]]$Arguments){Live $current;$r=RunOwned $current.cli (@('--json','--pid',[string]$current.pid,'--owner',$owner)+$Arguments);$lines=@($r.stdout-split'\r?\n'|Where-Object {$_-match'\S'});Require ($lines.Count-eq1) 'one actual CLI JSON record';$r.reply=$lines[0]|ConvertFrom-Json;return $r}
function Native($Object,[int]$Budget=2500){Live $current;if(-not$Object.ContainsKey('owner')){$Object.owner=$owner};$request=$Object|ConvertTo-Json -Compress;$wire=[ViR2Pipe]::Query([uint32]$current.pid,$current.retained_handle,$current.created,$current.path,$request,$Budget);$row=@{request=$request;complete=$wire.Complete;server_pid=$wire.ServerPid;text=$wire.Text;error=$wire.Error};$calls.Add($row);Require ($wire.Complete-and$wire.ServerPid-eq$current.pid-and-not$wire.Error) 'bounded current owned native pipe';$row.reply=$wire.Text|ConvertFrom-Json;Require ($row.reply.ok-is[bool]) 'typed native result';return $row.reply}
function Background{Live $current;[uint32]$fg=0;[void][ViWndProcAwNative]::GetWindowThreadProcessId([ViWndProcAwNative]::GetForegroundWindow(),[ref]$fg);Require ($fg-ne$current.pid) 'independent real foreground stays outside fixture'}
function Control([uint32]$Action){Live $current;$h=[IntPtr]::new([long][uint64]$current.ready.hwnd);[uint32]$pidValue=0;Require ([ViWndProcAwNative]::GetWindowThreadProcessId($h,[ref]$pidValue)-eq$current.ready.thread-and$pidValue-eq$current.pid) 'fresh exact own control HWND/PID/thread';$script:token++;$mine=$token;Require ([ViWndProcAwNative]::PostMessageW($h,0x80B8,[UIntPtr]::new([uint64]$Action),[IntPtr]::new([long]$mine))) 'own control accepted';$end=[Environment]::TickCount64+3500;do{$ack=@(Rows $current.log|Where-Object {$_.event-eq'control'-and$_.token-eq$mine})|Select-Object -Last 1;if($ack){Require ($ack.ok-is[bool]-and$ack.ok) 'typed exact control ACK';$snapshot=@(Rows $current.log|Where-Object {$_.event-eq'snapshot'-and$_.token-eq$mine})|Select-Object -Last 1;Require ($null-ne$snapshot) 'exact tokened consumer snapshot';return $snapshot};if($current.process.HasExited){throw 'fixture exited during own control'};Start-Sleep -Milliseconds 5}while([Environment]::TickCount64-lt$end);throw 'bounded fixture control ACK unavailable'}
function StartFixture([string]$Exe,[string]$CliPath,[string]$Dll,[string]$Name){
 $log=Join-Path $run ($Name+'.jsonl');$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$Exe;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;[void]$si.ArgumentList.Add($log);$p=[Diagnostics.Process]::new();$p.StartInfo=$si;Require ($p.Start()) 'owned sequence consumer started';$t=NewTracked $p $Exe;$script:current=$t;$t.cli=$CliPath;$t.log=$log;ValidateTracked $t
 $end=[Environment]::TickCount64+6000;do{$ready=@(Rows $log|Where-Object event -eq ready)|Select-Object -First 1;if($ready-or$p.HasExited){break};Start-Sleep -Milliseconds 10}while([Environment]::TickCount64-lt$end)
 $guard=@(Rows $log|Where-Object event -eq guards)|Select-Object -First 1;$t.ready=$ready;Background
 Require ($ready-and$ready.pid-eq$t.pid-and$ready.actual_offscreen_checked-and$guard.safe-and$guard.terminal_desktop_writers-eq19-and$guard.lower_keys-eq'fabricated all up'-and$guard.lower_focus-eq'fabricated outside/null'-and-not$guard.native_writer_called) 'actual pre-DLL terminal/fabricated/offscreen prerequisites'
 $before=Control 0;$t.before_dll=$before;Require ($before.mask-eq0-and$before.gks_mask-eq0-and$before.gkbs_mask-eq0-and$before.gkbs_ok) 'fabricated native keyboard is released before DLL'
 $r=Invoke-ViSequenceCli @('inject','--dll',$Dll,'--hooks-only');Require ($r.exit-eq0-and$r.reply.ok) 'real chosen DLL injected';$r=Native @{cmd='config';hwnd=('0x{0:X}'-f[uint64]$ready.hwnd);fakefocus=$true;autoactivate=$false;blockfocus=$true;isolate=$true;msgs='on'};Require ($r.ok-and$r.msgmode-eq1) 'exact current fixture adopted/configured'
 $r=Invoke-ViSequenceCli @('readiness');Require ($r.exit-eq0-and$r.reply.ok-and$r.reply.hook_ready-and$r.reply.window_ready-and$r.reply.queue_ready) 'fresh actual full queue readiness';$first=Control 0;Require ($first.mask-eq0-and$first.final_all_up) 'fresh actual virtual released control';return $t
}
function StartServer([string]$Name){
 $index=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath (Join-Path $McpBuildDir 'index.js')).Path);$code='setTimeout(()=>process.exit(124),45000).unref(); await import('+(([uri]$index).AbsoluteUri|ConvertTo-Json -Compress)+');'
 $si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$NodeExe;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardInput=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$si.WorkingDirectory=$run;foreach($arg in @('--input-type=module','--eval',$code)){[void]$si.ArgumentList.Add($arg)};$si.Environment['VINPUT_EXE']=$current.cli;$si.Environment['VINPUT_CAPTURE_DIR']="$run/captures";$si.Environment['VINPUT_OWNER']=$owner;$si.Environment['TEMP']="$run/temp";$si.Environment['TMP']="$run/temp"
 $p=[Diagnostics.Process]::new();$p.StartInfo=$si;Require ($p.Start()) 'owned real MCP server started';$t=NewTracked $p $NodeExe;$script:server=$t;$t.name=$Name;$t.wrapper=$code;$t.reader=[ViSequenceRpcReader]::new($p.StandardOutput);$t.stderr=[ViWndProcAwTail]::new($p.StandardError);ValidateTracked $t
 $init=Rpc 'initialize' @{protocolVersion='2024-11-05';capabilities=@{};clientInfo=@{name='owned-sequence-native';version='1'}} 6000;Require ($init.result.serverInfo.name-eq'llm-game-automation-mcp'-and$init.result.protocolVersion-is[string]) 'actual MCP initialized'
 SendNotification 'notifications/initialized' @{}
}
function SendNotification([string]$Method,$Params){Live $server;Live $current;$text=@{jsonrpc='2.0';method=$Method;params=$Params}|ConvertTo-Json -Compress -Depth 20;$errorText='';Require ([ViSequenceRpcReader]::Write($server.process.StandardInput,$text,1000,[ref]$errorText)) ('MCP notification write: '+$errorText)}
function Rpc([string]$Method,$Params,[int]$Budget=15000){
 Live $server;Live $current;$script:rpcId++;$mine=$rpcId;$request=@{jsonrpc='2.0';id=$mine;method=$Method;params=$Params};$row=@{id=$mine;request=$request;started_tick=[Environment]::TickCount64;response=$null;error=$null};$rpcCalls.Add($row);$text=$request|ConvertTo-Json -Depth 20 -Compress;$errorText='';Require ([ViSequenceRpcReader]::Write($server.process.StandardInput,$text,1000,[ref]$errorText)) ('MCP request write: '+$errorText);$end=[Environment]::TickCount64+$Budget
 do{Require (-not$server.reader.Error) ('MCP reader error: '+$server.reader.Error);$line=$null;while($server.reader.TryNext([ref]$line)){if(-not$line){continue};$reply=$line|ConvertFrom-Json;Require ($reply.jsonrpc-eq'2.0') 'actual JSON-RPC2 record';if(($reply.id-is[int]-or$reply.id-is[long])-and$reply.id-eq$mine){$row.response=$reply;$row.finished_tick=[Environment]::TickCount64;return $reply};$row.other_record=$reply};if($server.process.HasExited){throw 'MCP server exited before exact response'};Start-Sleep -Milliseconds 5}while([Environment]::TickCount64-lt$end);$row.error='MCP response deadline; input may already have started; never replayed';throw $row.error
}
function Tool([string]$Name,$Arguments,[int]$Budget=15000){$r=Rpc 'tools/call' @{name=$Name;arguments=$Arguments} $Budget;Require ($null-ne$r.result-and-not$r.error) 'actual MCP tool transport response';$texts=@($r.result.content|Where-Object type -eq text);Require ($texts.Count-ge1) 'actual MCP text receipt';$j=$texts[0].text|ConvertFrom-Json;return @{json=$j;is_error=($r.result.isError-eq$true);images=@($r.result.content|Where-Object type -eq image);raw=$r}}
function ValidJobId($Value){if($Value-isnot[string]){return $false};$m=[regex]::Match($Value,'^([1-9][0-9]{0,9}):([1-9][0-9]{0,19}):([1-9][0-9]{0,19})$');[uint32]$pidPart=0;[uint64]$epoch=0;[uint64]$serialPart=0;return $m.Success-and[uint32]::TryParse($m.Groups[1].Value,[ref]$pidPart)-and[uint64]::TryParse($m.Groups[2].Value,[ref]$epoch)-and[uint64]::TryParse($m.Groups[3].Value,[ref]$serialPart)-and$pidPart-eq$current.pid}
function WaitNativeJob([string]$Id,[int]$Budget=7000){$end=[Environment]::TickCount64+$Budget;do{$j=Native @{cmd='job-status';id=$Id};if(-not$j.ok-or$j.job.job_complete){return $j};Start-Sleep -Milliseconds 20}while([Environment]::TickCount64-lt$end);return $j}
function CheckReleased([string]$Name){$status=Native @{cmd='status'};$snapshot=Control 0;$keys=@(Rows $current.log|Where-Object {$_.event-eq'key_snapshot'-and$_.token-eq$snapshot.token-and$_.epoch-eq$snapshot.epoch});Check ($status.ok-and$null-ne$status.virtual_down-and@($status.virtual_down|Where-Object {$_-in@(117,118,16)}).Count-eq0) "$Name native virtual watched keys are released";Check ($snapshot.mask-eq0-and$snapshot.final_all_up-and$snapshot.chord_seen-and$snapshot.completed_latch) "$Name independent polling saw chord then release";Check ($keys.Count-eq3-and@($keys|Where-Object {$_.vk-in@(117,118)-and$_.high_samples-gt0-and$_.down_count-gt0-and$_.up_count-gt0-and$_.wm_down-gt0-and$_.wm_up-gt0}).Count-eq2) "$Name original WndProc and readers observed watched down/up";return @{status=$status;snapshot=$snapshot;keys=$keys}}
function ImageEvidence($Tool){$images=$Tool.images;if($images.Count-ne1){return @{ok=$false;reason='one inline image missing'}};try{Add-Type -AssemblyName System.Drawing;$bytes=[Convert]::FromBase64String($images[0].data);if($bytes.Length-gt1048576){throw 'image exceeds1MiB'};$stream=[IO.MemoryStream]::new($bytes);$bitmap=$null;try{$bitmap=[Drawing.Bitmap]::new($stream);$pixel=$bitmap.GetPixel([int]($bitmap.Width/2),[int]($bitmap.Height/2));return @{ok=$true;width=$bitmap.Width;height=$bitmap.Height;r=$pixel.R;g=$pixel.G;b=$pixel.B;mime=$images[0].mimeType}}finally{if($bitmap){$bitmap.Dispose()};$stream.Dispose()}}catch{return @{ok=$false;reason=$_.Exception.Message}}}
function StopActors{
 if($current){try{if(-not$current.process.HasExited){try{$null=Native @{cmd='release'};$null=Control 8;[void]$current.process.WaitForExit(800)}catch{}};Finish $current}finally{$current.process.Dispose();$current.Remove('process');$script:current=$null}}
 if($server){try{try{$server.process.StandardInput.Close()}catch{};[void]$server.process.WaitForExit(1500);Finish $server;$null=$server.reader.Wait(500);$null=$server.stderr.Wait(500);$server.stdio=@{reader_complete=$server.reader.Complete;reader_error=$server.reader.Error;reader_characters=$server.reader.Characters;stderr_complete=$server.stderr.Complete;stderr_error=$server.stderr.Error;stderr_characters=$server.stderr.Characters};[IO.File]::WriteAllText((Join-Path $run ($server.name+'.stdout_tail.log')),$server.reader.Tail());[IO.File]::WriteAllText((Join-Path $run ($server.name+'.stderr.log')),$server.stderr.Text());if(-not$server.reader.Complete-or$server.reader.Error-or-not$server.stderr.Complete-or$server.stderr.Error-or$server.stderr.Characters-gt65536-or($server.cleanup.native_exit_code-eq124-and-not$server.cleanup.termination_attempted)){$script:instrument=$false}}finally{$server.Remove('reader');$server.Remove('stderr');$server.process.Dispose();$server.Remove('process');$script:server=$null}}
}
